<?php defined('BASEPATH') or exit('No direct script access allowed'); ?><div id="widget-sc-clock" class="widget relative"><div class="panel_s"><div class="panel-body"><div class="widget-dragger"></div><h4 class="tw-font-semibold tw-mt-0"><i class="fa-regular fa-clock text-info"></i> Clock</h4><div id="sc-dashboard-clock" style="font-size:32px;font-weight:700"></div><div id="sc-dashboard-date" class="text-muted"></div><script>(function(){function t(){var d=new Date(),c=document.getElementById('sc-dashboard-clock'),x=document.getElementById('sc-dashboard-date');if(c)c.textContent=d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});if(x)x.textContent=d.toLocaleDateString([], {weekday:'long',year:'numeric',month:'long',day:'numeric'});}t();setInterval(t,1000);})();</script></div></div></div>